function v3_report_e3(T,out)
writetable(T,fullfile(out,'tables','E3_migration.csv'));old=fullfile(repo_root,'simulink','results','paper_experiments','20261105_paper_v2','tables','E3_valid_domain_followup.csv');if isfile(old),H=readtable(old);H=H(H.masked==0,:);writetable(H,fullfile(out,'tables','E3_historical_horizon.csv'));f=figure('Visible','off');tiledlayout(2,1);nexttile;plot(H.horizon,H.rmse_deg,'-o');ylabel('Historical RMSE (deg)');nexttile;plot(H.horizon,H.compute_mean_s,'-o');ylabel('Historical mean solve (s)');xlabel('Horizon (s)');v3_savefig(f,out,'E3_historical_horizon');end
f=figure('Visible','off');tiledlayout(4,1);names={'V3_L','V3_S','V3_Z'};colors=[.85 .325 .098;0 .447 .741;.35 .35 .35];data=cell(1,3);for k=1:3,path=fullfile(out,'E3','cases',names{k},'timeseries.csv');if ~isfile(path),continue;end;D=readtable(path);C=readtable(fullfile(out,'E3','cases',names{k},'cmg_timeseries.csv'));data{k}=C;ci=1:max(1,ceil(height(C)/2000)):height(C);idx=1:max(1,ceil(height(D)/2000)):height(D);nexttile(1);hold on;plot(D.time_s(idx),D.pitch_deg(idx),'Color',colors(k,:),'DisplayName',names{k});if k==1,plot(D.time_s(idx),D.ref_pitch_deg(idx),'k--','DisplayName','L/S reference');end;nexttile(2);hold on;plot(C.time_s(ci),C.Hy(ci),'Color',colors(k,:),'DisplayName',names{k});nexttile(3);hold on;plot(C.time_s(ci),rad2deg(C.movement_rad(ci)),'Color',colors(k,:),'DisplayName',names{k});nexttile(4);hold on;if k==1,plot(D.time_s(idx),D.aero_y_Nm(idx),'DisplayName','L aero');plot(D.time_s(idx),D.cmg_y_Nm(idx),'DisplayName','L CMG');end;end
labels={'Pitch (deg)','Hy (N m s)','Max gimbal travel (deg)','Pitch torque (N m)'};for k=1:4,nexttile(k);ylabel(labels{k});xline(35,'k:');xline(40,'k:');grid on;legend('Location','best');end;nexttile(3);yline(10,'k--');nexttile(4);xlabel('Time (s)');v3_savefig(f,out,'E3_migration');
if ~isempty(data{1}) && ~isempty(data{3}),A=data{1};B=data{3};t=A.time_s(A.time_s<=B.time_s(end));z=interp1(B.time_s,[B.Hy B.g1 B.g2 B.g3 B.g4],t);D=[A.Hy(1:numel(t)),A.g1(1:numel(t)),A.g2(1:numel(t)),A.g3(1:numel(t)),A.g4(1:numel(t))]-z;writetable(array2table([t,D],'VariableNames',{'time_s','delta_Hy','delta_g1','delta_g2','delta_g3','delta_g4'}),fullfile(out,'tables','E3_L_minus_Z.csv'));end
end
